# Instalación
composer require predis/predis

# Configurar en .env
REDIS_HOST=127.0.0.1
REDIS_PORT=6379

# Uso en PHP
$redis = new Predis\Client();

// Guardar resultado de consulta en cache (5 min)
$key = "usuario:$userId:perfil";
if ($redis->exists($key)) {
    $perfil = json_decode($redis->get($key));
} else {
    $perfil = $db->query("SELECT * FROM usuarios WHERE id = ?", $userId);
    $redis->setex($key, 300, json_encode($perfil));
}

// Invalidar cache al actualizar
$redis->del("usuario:$userId:perfil");
